import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";

import * as Avatar from "../../ui/avatar";

// MODEL

export const Model = S.Struct({});

export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const avatarImageSrc =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%230f172a'/%3E%3Ctext x='40' y='48' text-anchor='middle' font-size='24' font-family='Arial' fill='white'%3ELT%3C/text%3E%3C/svg%3E";

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    Avatar.groupView<Message>(
      [
        Avatar.view<Message>({
          alt: "Lena Taylor",
          fallback: "LT",
          src: avatarImageSrc,
        }),
        Avatar.view<Message>({ fallback: "LT" }),
      ],
      "gap-3"
    )
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeProgram({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Avatar Basic",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as AvatarBasicExample from "./main";

describe("Avatar Basic example", () => {
  test("matches the Base UI default two avatar example", () => {
    Scene.scene(
      { update: AvatarBasicExample.update, view: AvatarBasicExample.view },
      Scene.with(AvatarBasicExample.init()[0]),
      Scene.expect(Scene.role("img", { name: "Lena Taylor" })).toExist(),
      Scene.expect(Scene.text("LT")).toExist(),
      Scene.expect(Scene.text("LT")).not.toHaveHandler("click")
    );
  });
});
